    blockstun: 14,
    hitPushback: px(6),
    blockPushback: px(4),
    launch: 0,
    advance: 0,
    strikeInvulnerable: 0,
    guardStaminaCost: G.heavy,
  },
  {
    // Worker's choice (§7 leaves it open): slower than the heavy mid, lifts the defender into a short juggle.
    timing: { id: "launcher", name: "Launcher", startup: 16, active: 4, recovery: 28, onBlock: { kind: "frames", advantage: -18 } },
    kind: "strike",
    category: "heavy",
    stance: "standing",
    guard: "mid",
    hitbox: { x: px(12), y: px(16), w: px(40), h: px(64) },
