  },
  {
    // Worker's choice: the universal anti-air, a fast upward swing; high, so it passes over a crouching fighter.
    timing: { id: "anti-air", name: "Anti-air", startup: 6, active: 5, recovery: 20, onBlock: { kind: "frames", advantage: -14 } },
    kind: "strike",
