];

export const duelistMoveset: DuelMoveset = {
  rules: duelRules,
  arena: duelArena,
  fighter: duelistFighter,
  moves: duelistMoves,
  commands: {
    light: "jab",
    downLight: "anti-air",
    heavy: "heavy-mid",
    downHeavy: "low-sweep",
    forwardHeavy: "launcher",
    special1: "advancing-thrust",
    special2: "counter-slash",
    throw: "throw",
  },
