/** Identifies everything in this file: the hash of `duelistMoveset`, so any change to the data changes it. */
export const MOVESET_VERSION = movesetVersion(duelistMoveset);
import type { DuelMoveset } from "./schema.js";

/**
 * Canonical JSON (object keys sorted, safe integers only), the same text `hashState` in `packages/simulation` hashes,
 * so a moveset's version is also its state hash.
 */
function canonical(value: unknown): string {
  if (value === null) return "null";
  switch (typeof value) {
    case "number":
      if (!Number.isSafeInteger(value)) throw new TypeError(`move data numbers must be safe integers, got ${value}`);
      return String(value);
    case "string":
      return JSON.stringify(value);
    case "boolean":
      return value ? "true" : "false";
    case "object": {
      if (Array.isArray(value)) return `[${value.map(canonical).join(",")}]`;
      const entries = Object.keys(value)
        .sort()
        .filter((key) => (value as Record<string, unknown>)[key] !== undefined)
        .map((key) => `${JSON.stringify(key)}:${canonical((value as Record<string, unknown>)[key])}`);
      return `{${entries.join(",")}}`;
    }
    default:
      throw new TypeError(`move data cannot hold a ${typeof value}`);
  }
}

const FNV_OFFSET = 0xcbf29ce484222325n;
const FNV_PRIME = 0x100000001b3n;
const MASK_64 = 0xffffffffffffffffn;

/** 64-bit FNV-1a over the UTF-16 code units of a string, as 16 hex digits. */
function fnv1a64(text: string): string {
  let hash = FNV_OFFSET;
  for (let index = 0; index < text.length; index++) {
    const unit = text.charCodeAt(index);
    hash = ((hash ^ BigInt(unit & 0xff)) * FNV_PRIME) & MASK_64;
    hash = ((hash ^ BigInt(unit >>> 8)) * FNV_PRIME) & MASK_64;
  }
  return hash.toString(16).padStart(16, "0");
}

/** Move data is immutable, so each moveset object is hashed once. */
const versions = new WeakMap<DuelMoveset, string>();

/**
 * Identifies a moveset by its data: the 64-bit hash of all of it. A duel state records it, and restoring, replaying
 * or stepping a duel against other data is refused, so changed data can never keep an old version.
 */
export function movesetVersion(moveset: DuelMoveset): string {
  let version = versions.get(moveset);
  if (version === undefined) {
    version = fnv1a64(canonical(moveset));
    versions.set(moveset, version);
  }
  return version;
}
export * from "./input.js";
export * from "./schema.js";
export * from "./version.js";
export * from "./duelist.js";
export * from "./inputLog.js";
/**
 * One player's duel input for one frame: a bit field of held directions and buttons (§8). Directions are absolute
 * (left is towards x = 0), not relative to facing, and are kept as separate bits so that the step itself resolves
 * left + right (and up + down) to neutral. Throw is light and heavy together; there is no separate throw bit.
 */
export const DUEL_INPUT = {
  left: 1 << 0,
  right: 1 << 1,
  up: 1 << 2,
  down: 1 << 3,
  light: 1 << 4,
  heavy: 1 << 5,
  special1: 1 << 6,
  special2: 1 << 7,
  dash: 1 << 8,
} as const;

/** Every defined bit; a duel input is an integer in [0, DUEL_INPUT_MASK]. */
export const DUEL_INPUT_MASK = 0x1ff;

/** The buttons the input buffer remembers, in the order the step checks them. */
export const DUEL_BUTTONS = ["light", "heavy", "special1", "special2", "dash"] as const;

export type DuelButton = (typeof DUEL_BUTTONS)[number];
import { z } from "zod";
import { formatIssues, type ValidationResult } from "../rules.js";
import { DUEL_INPUT_MASK } from "./input.js";

export const DUEL_INPUT_LOG_FORMAT = "pirate-sea-race/duel-input-log";

/** One player's input bits for one frame. Unknown bits are refused, not masked. */
export const duelInputSchema = z.int().min(0).max(DUEL_INPUT_MASK);

/**
 * A recorded duel, as JSON:
 *
 * ```json
 * { "format": "pirate-sea-race/duel-input-log", "version": 1, "movesetVersion": "<16 hex digits>",
 *   "startFrame": 0, "inputs": [[0, 0], [2, 1], [2, 17]] }
 * ```
 *
 * `inputs[i]` holds player one's and player two's input bits (`DUEL_INPUT`) for duel frame `startFrame + i + 1`,
 * so a log that starts from a state at frame N replays from that state. `movesetVersion` must match the move data
 * and the starting state (`movesetVersion()` of the moveset).
 */
export const duelInputLogSchema = z.strictObject({
  format: z.literal(DUEL_INPUT_LOG_FORMAT),
  version: z.literal(1),
  movesetVersion: z.string().min(1),
  startFrame: z.int().nonnegative(),
  inputs: z.array(z.tuple([duelInputSchema, duelInputSchema])),
});

export type DuelInputLog = z.infer<typeof duelInputLogSchema>;

export function validateDuelInputLog(candidate: unknown): ValidationResult<DuelInputLog> {
  const parsed = duelInputLogSchema.safeParse(candidate);
  return parsed.success ? { ok: true, value: parsed.data } : { ok: false, issues: formatIssues(parsed.error) };
}
import { z } from "zod";
import { formatIssues, type ValidationResult } from "./rules.js";

/** How the attacker stands after the defender blocks (§8): a frame advantage, or one of the table's special cases. */
export const onBlockSchema = z.discriminatedUnion("kind", [
  /** Negative is minus: "Minus 12" is `{ kind: "frames", advantage: -12 }`. */
  z.strictObject({ kind: z.literal("frames"), advantage: z.int() }),
  z.strictObject({ kind: z.literal("spacing-dependent") }),
  z.strictObject({ kind: z.literal("unguardable") }),
]);

/**
 * One row of the baseline frame budgets (§8), in 60 Hz frames. `active` is `"projectile-life"` when the hit lives on
 * a projectile rather than the fighter.
 */
export const moveTimingSchema = z
  .strictObject({
    id: z.string().regex(/^[a-z][a-z0-9-]*$/),
    name: z.string().min(1),
    startup: z.int().positive(),
    active: z.union([z.int().positive(), z.literal("projectile-life")]),
    recovery: z.int().nonnegative(),
    onBlock: onBlockSchema,
  })
  .superRefine((move, ctx) => {
    // Advantage on block is blockstun minus the attacker's remaining active and recovery frames. Blockstun is never
    // negative, so the attacker can never be more minus than active + recovery.
    if (move.onBlock.kind === "frames" && typeof move.active === "number" && move.onBlock.advantage < -(move.active + move.recovery)) {
      ctx.addIssue({
        code: "custom",
        path: ["onBlock", "advantage"],
        message: `minus ${-move.onBlock.advantage} on block exceeds active + recovery (${move.active + move.recovery} frames)`,
      });
    }
  });

export type MoveTiming = z.infer<typeof moveTimingSchema>;

export const baselineFrameBudgets = [
  { id: "jab", name: "Jab", startup: 7, active: 3, recovery: 12, onBlock: { kind: "frames", advantage: -2 } },
  { id: "heavy-mid", name: "Heavy mid", startup: 18, active: 4, recovery: 24, onBlock: { kind: "frames", advantage: -12 } },
  { id: "low-sweep", name: "Low sweep", startup: 20, active: 3, recovery: 26, onBlock: { kind: "frames", advantage: -15 } },
  { id: "projectile-special", name: "Projectile special", startup: 22, active: "projectile-life", recovery: 30, onBlock: { kind: "spacing-dependent" } },
  { id: "throw", name: "Throw", startup: 12, active: 2, recovery: 24, onBlock: { kind: "unguardable" } },
] as const satisfies readonly MoveTiming[];

export function validateMoveTiming(candidate: unknown): ValidationResult<MoveTiming> {
  const parsed = moveTimingSchema.safeParse(candidate);
  return parsed.success ? { ok: true, value: parsed.data } : { ok: false, issues: formatIssues(parsed.error) };
}

/** Validates a whole table: every row, and no id used twice. */
export function validateFrameBudgets(candidate: unknown): ValidationResult<MoveTiming[]> {
  const parsed = z.array(moveTimingSchema).safeParse(candidate);
  if (!parsed.success) return { ok: false, issues: formatIssues(parsed.error) };
  const seen = new Set<string>();
  const issues: string[] = [];
  for (const move of parsed.data) {
    if (seen.has(move.id)) issues.push(`${move.id}: duplicate move id`);
    seen.add(move.id);
  }
  return issues.length > 0 ? { ok: false, issues } : { ok: true, value: parsed.data };
}

