export const DUEL_INPUT = {
  left: 1 << 0,
  right: 1 << 1,
  up: 1 << 2,
  down: 1 << 3,
  light: 1 << 4,
  heavy: 1 << 5,
  special1: 1 << 6,
  special2: 1 << 7,
  dash: 1 << 8,
