// Throwaway recorder for mirror.test.ts golden data, run against the base commit.
const ROOT = process.argv[2]!;
const duel = await import(`${ROOT}/packages/simulation/src/duel/index.ts`);
const { nextInt } = await import(`${ROOT}/packages/simulation/src/random.ts`);
const { createDuelState, defaultDuelConfig: config, stepDuel, hashState, duelInput: I } = duel;

// --- generator (copied verbatim into mirror.test.ts) ---
function mirrorInputs(seed: number, frames: number): [number, number][] {
  let rng = seed;
  const draw = (bound: number) => {
    const drawn = nextInt(rng, bound);
    rng = drawn.state;
    return drawn.value;
  };
  const held = [0, 0];
  const left = [0, 0];
  const inputs: [number, number][] = [];
  for (let frame = 0; frame < frames; frame++) {
    for (const player of [0, 1] as const) {
      if (left[player] === 0) {
        const back = player === 0 ? I("left") : I("right");
        const forward = player === 0 ? I("right") : I("left");
        const moves = [0, back, back, back, back | I("down"), back | I("down"), forward, forward, forward, I("down"), I("up"), I("up") | forward, I("up") | back, I("dash"), back | I("dash"), I("left", "right")];
        const attacks = [I("light"), I("light"), I("heavy"), I("down", "heavy"), forward | I("heavy"), I("down", "light"), I("special1"), I("special2"), I("light", "heavy"), I("light", "heavy")];
        const attack = draw(100) < 22;
        held[player] = attack ? attacks[draw(attacks.length)]! : moves[draw(moves.length)]!;
        left[player] = attack ? 1 + draw(2) : 1 + draw(24);
      }
      left[player]!--;
    }
    inputs.push([held[0]!, held[1]!]);
  }
  return inputs;
}
// --- end generator ---

const LEGACY = ["x","y","vx","vy","facing","health","stamina","staminaIdle","action","actionFrame","timer","moveId","moveHit","crouching","combo","held","buffer"];
function legacy(state: any) {
  return {
    frame: state.frame, phase: state.phase, rng: state.rng,
    fighters: state.fighters.map((f: any) => Object.fromEntries(LEGACY.map((k) => [k, f[k]]))),
    events: state.events, result: state.result,
  };
}
const seeds = process.argv.slice(3).map(Number);
const out: any[] = [];
let total = 0;
for (const seed of seeds) {
  const inputs = mirrorInputs(seed, 4200);
  let state = createDuelState(config, { seed });
  const hashes: string[] = [hashState(legacy(state))];
  const checkpoints: string[] = [JSON.stringify(legacy(state))];
  let frames = 0;
  for (const pair of inputs) {
    state = stepDuel(config, state, pair);
    hashes.push(hashState(legacy(state)));
    if (state.frame % 300 === 0) checkpoints.push(JSON.stringify(legacy(state)));
    frames++;
    if (state.result !== null) break;
  }
  total += frames;
  const kinds = new Set<string>();
  // recount kinds
  out.push({ seed, frames, result: state.result, hashes, checkpoints });
  console.error(`seed ${seed}: ${frames} frames, result ${JSON.stringify(state.result)} health ${state.fighters.map((f: any) => f.health)}`);
}
console.error(`total ${total}`);
const block = out.map((d) => `  {\n    seed: ${d.seed},\n    frames: ${d.frames},\n    result: ${JSON.stringify(d.result)},\n    hashes: "${d.hashes.join("")}",\n    checkpoints: [\n${d.checkpoints.map((c: string) => `      ${JSON.stringify(c)},`).join("\n")}\n    ],\n  },`).join("\n");
process.stdout.write(`const GOLDEN: readonly GoldenDuel[] = [\n${block}\n];\n`);
EOF
