new_timing = '''/**
 * §8's move timing, restricted to what a fighter's own move can be: numeric active frames, and a frame advantage on
 * block, unguardable (a throw) or spacing-dependent (a move that never strikes with its own hitbox, such as a
 * projectile cast: what it leaves depends on its entity). The rows go through §8's own schema, so its rules (positive
 * startup and active frames, block advantage within active + recovery) are checked in one place.
 */
export const duelMoveTimingSchema = moveTimingSchema.transform((timing, ctx) => {
  const { active } = timing;
  if (active === "projectile-life") {
    ctx.issues.push({ code: "custom", input: active, path: ["active"], message: "a fighter's move needs a number of active frames" });
