new_move = '''export const moveCategorySchema = z.enum(["light", "heavy", "special", "throw"]);
export type MoveCategory = z.infer<typeof moveCategorySchema>;

/**
 * What a move does on its active frames. `strike` moves (throws included) connect with their own hitbox; the others
 * never do: a `projectile` move releases its bolt, a `zone` move lays its zone, and a `feint` only moves its fighter.
 * `strikesWithHitbox` is the one rule for which moves strike.
 */
export const moveEffectSchema = z.enum(["strike", "projectile", "zone", "feint"]);
export type MoveEffect = z.infer<typeof moveEffectSchema>;

/** The guard levels a strike can have; only a throw is unguardable. */
const strikeGuardSchema = z.enum(["high", "mid", "low"]);

/**
 * The bolt a `projectile` move releases on its first active frame. It flies straight at `speed`, strikes once like a
 * strike of the fighter's own (the same guard, stun, pushback and stamina rules), and dies on contact, at a wall or
 * after `life` frames. `id` names it in events; it is never a fighter's move.
 */
export const duelProjectileSchema = z.strictObject({
  id: z.string().regex(/^[a-z][a-z0-9-]*$/),
  name: z.string().min(1),
  /** Where the bolt appears, relative to the caster's origin for a caster facing right. */
  spawn: z.strictObject({ x: z.int(), y: z.int().nonnegative() }),
  /** Relative to the bolt's position, for a bolt flying right. */
  box: boxSchema,
  /** Sub-pixels per frame. */
  speed: z.int().positive(),
  /** Frames the bolt exists, the one it appears on included. */
  life: z.int().positive(),
  guard: strikeGuardSchema,
  damage: z.int().positive(),
  hitstun: z.int().positive(),
  blockstun: z.int().positive(),
  hitPushback: z.int().nonnegative(),
  blockPushback: z.int().nonnegative(),
  guardStaminaCost: z.int().nonnegative(),
});

export type DuelProjectile = z.infer<typeof duelProjectileSchema>;

/**
 * The timed zone a `zone` move lays on its first active frame, where the caster stands. It never strikes; it marks
 * the fighters whose hurtbox is inside it (the renderer obscures their startups, never their position or health).
 */
export const duelZoneSchema = z.strictObject({
  /** Relative to the caster's origin at the cast, for a caster facing right. */
  box: boxSchema,
  /** Frames the zone exists, the one it appears on included. */
  life: z.int().positive(),
});

export type DuelZone = z.infer<typeof duelZoneSchema>;

/** The normal commands a move can be cancelled into (never a special). */
export const cancelCommandSchema = z.enum(["light", "downLight", "heavy", "downHeavy", "forwardHeavy", "throw"]);
export type CancelCommand = z.infer<typeof cancelCommandSchema>;

/**
 * A feint's cancel: from move frame `opens` on, a buffered normal in `into` replaces the rest of the move. It opens
 * only after the feint's readable reappearance (`FEINT_REAPPEARANCE_FRAMES` of recovery).
 */
export const duelCancelSchema = z.strictObject({
  opens: z.int().positive(),
  into: z.array(cancelCommandSchema).min(1).readonly(),
});

export type DuelCancel = z.infer<typeof duelCancelSchema>;

/**
 * Recovery frames at the end of every feint dash that nothing can cancel and no invulnerability covers: Smoke's
 * readable reappearance (§9).
 */
export const FEINT_REAPPEARANCE_FRAMES = 12;

/**
 * One move. Frame counts are 60 Hz frames: `startup` frames come before the first active frame, then `active`, then
 * `recovery`. Distances and velocities are sub-pixels (per frame). A move that does not strike with its hitbox
 * (`effect` other than `strike`) keeps a hitbox for drawing, but its own damage, stun and pushback are 0.
 */
export const duelMoveSchema = z
  .strictObject({
    timing: duelMoveTimingSchema,
    kind: z.enum(["strike", "throw"]),
    effect: moveEffectSchema,
    /** Decides what blocking it costs (§7) and which rules apply. */
    category: moveCategorySchema,
    /** The hurtbox the attacker uses while performing the move. */
    stance: z.enum(["standing", "crouching"]),
    guard: guardLevelSchema,
    /** One box for the whole active phase. */
    hitbox: boxSchema,
    /** Before combo scaling. */
    damage: count,
    /** Frames the defender cannot act after a hit, counting the contact frame; for a throw, the knockdown after it. */
    hitstun: count,
    /** Frames the defender cannot act after blocking, counting the contact frame; 0 for a throw. */
    blockstun: count,
    hitPushback: count,
    blockPushback: count,
    /** Upward velocity given to the defender on hit (sub-pixels per frame); 0 leaves a grounded defender grounded. */
    launch: count,
    /** Forward velocity of the attacker during startup and active frames. */
    advance: count,
    /** Frames from the move's first frame during which strikes (bolts included) pass through the attacker. */
    strikeInvulnerable: count,
    /** Stamina the defender spends to block it. */
    guardStaminaCost: count,
    /** Exactly when `effect` is `projectile`. */
    projectile: duelProjectileSchema.optional(),
    /** Exactly when `effect` is `zone`. */
    zone: duelZoneSchema.optional(),
    /** Only on a `feint`. */
    cancel: duelCancelSchema.optional(),
  })
  .superRefine((move, ctx) => {
    const { timing } = move;
    const isThrow = move.kind === "throw";
    if (isThrow !== (move.category === "throw") || isThrow !== (move.guard === "unguardable")) {
      ctx.addIssue({ code: "custom", path: ["kind"], message: "a throw, and only a throw, has the throw category and is unguardable" });
    }
    if ((move.effect === "projectile") !== (move.projectile !== undefined)) {
      ctx.addIssue({ code: "custom", path: ["projectile"], message: "a projectile move, and only a projectile move, has projectile data" });
    }
    if ((move.effect === "zone") !== (move.zone !== undefined)) {
      ctx.addIssue({ code: "custom", path: ["zone"], message: "a zone move, and only a zone move, has zone data" });
    }
    if (move.cancel !== undefined && move.effect !== "feint") {
      ctx.addIssue({ code: "custom", path: ["cancel"], message: "only a feint can be cancelled" });
    }
    if (move.damage === 0 && move.effect === "strike") ctx.addIssue({ code: "custom", path: ["damage"], message: "a strike deals damage" });
    if (move.hitstun === 0 && move.effect === "strike") ctx.addIssue({ code: "custom", path: ["hitstun"], message: "a strike has hitstun" });
    if (move.effect !== "strike") {
      // It never connects: nothing of its own to deal, and nothing to block.
      if (isThrow) ctx.addIssue({ code: "custom", path: ["effect"], message: "a throw strikes with its hitbox" });
      for (const field of ["damage", "hitstun", "blockstun", "hitPushback", "blockPushback", "launch", "guardStaminaCost"] as const) {
        if (move[field] !== 0) ctx.addIssue({ code: "custom", path: [field], message: `a ${move.effect} move never strikes, so its ${field} is 0` });
      }
      if (timing.onBlock.kind !== "spacing-dependent") {
        ctx.addIssue({ code: "custom", path: ["timing", "onBlock"], message: "a move that never strikes is spacing-dependent on block" });
      }
    } else if (isThrow) {
      if (timing.onBlock.kind !== "unguardable") ctx.addIssue({ code: "custom", path: ["timing", "onBlock"], message: "a throw is unguardable" });
      if (move.blockstun !== 0) ctx.addIssue({ code: "custom", path: ["blockstun"], message: "a throw cannot be blocked" });
    } else if (timing.onBlock.kind !== "frames") {
      ctx.addIssue({ code: "custom", path: ["timing", "onBlock"], message: "a strike needs a frame advantage on block" });
    } else if (move.blockstun !== timing.active + timing.recovery + timing.onBlock.advantage) {
      // Contact on the first active frame, which is also the defender's first blockstun frame.
      ctx.addIssue({
        code: "custom",
        path: ["blockstun"],
        message: `blockstun ${move.blockstun} does not give ${timing.onBlock.advantage} on block (needs ${timing.active + timing.recovery + timing.onBlock.advantage})`,
      });
    }
    if (move.strikeInvulnerable > timing.startup) {
      ctx.addIssue({ code: "custom", path: ["strikeInvulnerable"], message: "strike invulnerability cannot outlast startup" });
    }
    if (move.effect === "feint") {
      if (timing.recovery < FEINT_REAPPEARANCE_FRAMES) {
        ctx.addIssue({ code: "custom", path: ["timing", "recovery"], message: `a feint's recovery holds its ${FEINT_REAPPEARANCE_FRAMES} reappearance frames` });
      }
      const reappeared = timing.startup + timing.active + FEINT_REAPPEARANCE_FRAMES;
      if (move.cancel !== undefined && (move.cancel.opens <= reappeared || move.cancel.opens > reappeared - FEINT_REAPPEARANCE_FRAMES + timing.recovery)) {
        ctx.addIssue({ code: "custom", path: ["cancel", "opens"], message: `a feint's cancel opens after its reappearance (frame ${reappeared}) and within its recovery` });
      }
    }
  });

'''
s = s.replace(old_move_start, new_move)
open(p,'w').write(s)
